import {VERSION,NEX_STEPS,ATTRS,CLASSES,TRACKS,ORIGINS,SKILLS,SKILL_GRADES,RITUAL_COST,initialCharacter,derive,validate,nexTier,originOf,attrBudget,effectiveGrade,rollPool,spend,recover,changeNex} from './rules.mjs';

const KEY='ordem-paranormal-campaigns-v2';
const LEGACY_KEY='ordem-paranormal-v12-isolated';
const $=id=>document.getElementById(id);
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const attr=s=>esc(s);
const opts=(values,active,placeholder='Selecionar')=>`<option value="">${esc(placeholder)}</option>`+values.map(v=>{const val=typeof v==='string'?v:v.value,label=typeof v==='string'?v:v.label;return `<option value="${attr(val)}" ${String(val)===String(active)?'selected':''}>${esc(label)}</option>`}).join('');
const clean=t=>String(t||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLocaleLowerCase('pt-BR').trim();
const numeric=(x,def=0)=>Number.isFinite(Number(x))?Math.trunc(Number(x)):def;
const uid=()=>globalThis.crypto?.randomUUID?.()||`00000000-0000-4000-8000-${Math.random().toString(16).slice(2,14).padEnd(12,'0')}`;
let ritualModal={open:false,search:'',element:'Todos',circle:0,expanded:''};
let equipmentModal={open:false,search:'',type:'Todos',expanded:'',mode:'items'};
let abilityModal={open:false,search:'',group:'Combatente',track:'Todos',expanded:'',own:false};
let expandedItems=new Set();
let expandedWeaponDetails=new Set();
let expandedRituals=new Set();
let editingRituals=new Set();
let editorModal='';
let state={active:'',activeCampaign:'',campaigns:[],characters:[]},tab='ficha',view='campaigns',shared=null,ready=false,remoteLoading=false,syncTimers=new Map(),draft=null,wizardStep=0;
const campaign=()=>state.campaigns.find(x=>x.id===state.activeCampaign);
const campaignChars=()=>state.characters.filter(x=>x.campaignId===state.activeCampaign);
function read(){try{const raw=JSON.parse(localStorage.getItem(KEY)||'null');if(raw&&Array.isArray(raw.campaigns)&&Array.isArray(raw.characters)){state={active:raw.active||'',activeCampaign:raw.activeCampaign||'',campaigns:raw.campaigns,characters:raw.characters.map(restoreCharacterCatalog)};return}}catch(e){console.warn(e)}
  // One-way, non-destructive migration from the previous local-only version.
  try{const old=JSON.parse(localStorage.getItem(LEGACY_KEY)||'null');if(old&&Array.isArray(old.characters)&&old.characters.length){const id=uid();state={active:old.active||'',activeCampaign:'',campaigns:[{id,name:'Campanha importada'}],characters:old.characters.map(c=>restoreCharacterCatalog({...c,campaignId:id}))};localStorage.setItem(KEY,JSON.stringify(state));return}}catch(e){console.warn(e)}
}
function persist(){try{localStorage.setItem(KEY,JSON.stringify(state));if($('op-save-status'))$('op-save-status').textContent=shared?'Sincronizando…':'✓ Salvo neste navegador';}catch(e){if($('op-save-status'))$('op-save-status').textContent='⚠ Falha ao salvar';console.error(e)}}
function make(){const c=initialCharacter();c.id=uid();c.campaignId=state.activeCampaign;c.lastEdited=new Date().toISOString();return c;}
function ensure(){if(!state.campaigns.some(c=>c.id===state.activeCampaign))state.activeCampaign='';const list=campaignChars();if(!list.some(c=>c.id===state.active))state.active=list[0]?.id||'';}
function active(){return campaignChars().find(x=>x.id===state.active)||campaignChars()[0]||null;}
function syncError(e){console.error('Sincronização:',e);toast('Falha na sincronização. Verifique a conexão.');if($('op-save-status'))$('op-save-status').textContent='⚠ Não sincronizado';}
function enqueue(id,work){const prior=syncTimers.get(id)||Promise.resolve();const next=prior.catch(()=>{}).then(work);syncTimers.set(id,next);next.catch(syncError);return next;}
function commit(){const c=active();if(!c)return;c.lastEdited=new Date().toISOString();persist();render();if(editorModal)refreshEditorModal();if(shared){const snapshot=structuredClone(c);enqueue(c.id,async()=>{await syncTimers.get(snapshot.campaignId);await shared.saveCharacter(snapshot);if($('op-save-status'))$('op-save-status').textContent='✓ Sincronizado'})}}
function toast(message){const el=$('op-toast');if(!el)return;el.textContent=message;el.classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.classList.remove('show'),3200)}
const cap=n=>n>0?`+${n}`:`${n}`;
const isWeaponItem=x=>x?.type==='Arma'||(Boolean(x?.damage)&&x?.type!=='Munição');
// Restore weapon statistics on old saves that stored only a name and inventory capacity.
export function completeWeaponData(item){
 if(!item||!isWeaponItem(item))return item;
 const base=WEAPONS.find(w=>(item.catalogId&&w.id===item.catalogId)||clean(w.name)===clean(item.name));
 if(!base)return item;
 const merged={...item};
 for(const key of ['damage','critical','range','damageType','group','proficiency']){
  if(merged[key]===undefined||merged[key]===null||merged[key]==='')merged[key]=base[key]??'';
 }
 if(!merged.catalogId)merged.catalogId=base.id;
 return merged;
}
// Enrich imported legacy entries with the local rules catalogue without replacing user edits.
function restoreCharacterCatalog(c){
 if(Array.isArray(c.items))c.items=c.items.map(completeWeaponData);
 if(Array.isArray(c.abilities))c.abilities=c.abilities.map(a=>{
  if(!a||typeof a!== 'object')return a;
  const match=ABILITY_CATALOG.find(x=>(a.catalogId&&x.id===a.catalogId)||clean(x.name)===clean(a.name));
  if(!match)return a;
  return {...a,catalogId:a.catalogId||match.id,group:a.group||match.group,track:a.track||match.track,description:a.description||match.description||'',page:a.page||match.page};
 });
 if(Array.isArray(c.rituals))c.rituals=c.rituals.map(r=>{
  if(!r||typeof r!=='object')return r;
  const candidates=RITUALS.filter(x=>(r.catalogId&&x.id===r.catalogId)||clean(x.name)===clean(r.name));
  const match=candidates.find(x=>r.catalogId&&x.id===r.catalogId)||candidates.find(x=>r.element&&clean(x.element)===clean(r.element))||(candidates.length===1?candidates[0]:null);
  if(!match)return {...r,needsCatalogSelection:candidates.length>1};
  const verified=createFromCatalog('rituals',match.id);
  if(!verified)return r;
  const merged={...r,catalogId:r.catalogId||match.id,needsCatalogSelection:false};
  for(const key of ['summary','casting','range','target','area','duration','resistance','damage','discenteDamage','verdadeiroDamage','element','circle']){
   if(merged[key]===undefined||merged[key]===null||merged[key]==='')merged[key]=verified[key];
  }
  return merged;
 });
 return c;
}
const diceNotation=(attribute,bonus=0)=>`${numeric(attribute)===0?'2d20 (menor)':`${numeric(attribute)}d20 (maior)`}${bonus?` ${cap(bonus)}`:''}`;

function renderCampaigns(){
  $('op-landing').hidden=false;$('op-workspace').hidden=true;$('op-campaign-bar').hidden=true;
  $('op-landing').innerHTML=`<div class="op-landing-intro"><div class="op-section-eyebrow">CENTRAL DE INVESTIGAÇÕES</div><h2>Suas campanhas</h2><p>Entre em uma investigação ou crie um novo arquivo. Sem login, sem perfis: todos podem acessar as fichas.</p></div><form id="op-create-form" class="op-create-row"><label for="campaign-name">Nova campanha</label><div><input id="campaign-name" maxlength="120" required placeholder="Ex.: O Mistério de Santa Aurora"><button class="op-btn op-btn-primary" type="submit">+ Criar campanha</button></div></form><div class="op-campaign-grid">${state.campaigns.map(c=>`<article class="op-campaign-card"><span class="op-section-eyebrow">DOSSIÊ DE CAMPANHA</span><h3>${esc(c.name)}</h3><p>${state.characters.filter(x=>x.campaignId===c.id).length} ficha(s) de personagem</p><div class="op-campaign-actions"><button class="op-btn op-btn-primary" data-action="open-campaign" data-id="${attr(c.id)}">Abrir campanha →</button><button class="op-btn op-btn-danger" data-action="delete-campaign" data-id="${attr(c.id)}" aria-label="Excluir campanha ${attr(c.name)}">Excluir</button></div></article>`).join('')||'<div class="op-empty">Nenhuma campanha ainda. Crie sua primeira investigação acima.</div>'}</div>`;
}
function renderMaster(){const chars=campaignChars();$('op-hero').innerHTML=`<div class="op-master-heading"><div><span class="op-section-eyebrow">VISÃO DO MESTRE</span><h2>Painel da sessão</h2><p>Resumo de todos os agentes de ${esc(campaign()?.name||'esta campanha')}. Abra qualquer ficha para editar.</p></div><span class="op-tag">${chars.length} agente(s)</span></div>`;$('op-tabs').innerHTML='';
 $('op-content').innerHTML=`<div class="op-master-grid">${chars.map(c=>{let d;try{d=derive(c)}catch(e){return `<article class="op-card"><h3>${esc(c.name)}</h3><p class="op-error">Ficha inválida</p></article>`}return `<article class="op-card op-master-card"><div class="op-master-cardtop"><span class="op-agent-avatar">${esc((c.icon||c.name||'?').trim().slice(0,3))}</span><div><h3>${esc(c.name||'Agente')}</h3><small>${esc(c.player||'Jogador não indicado')} · ${esc(CLASSES[c.classId]?.title||'Agente')} · NEX ${c.nex}%</small></div></div><div class="op-master-meters">${[['pv','PV',d.pv],['pe','PE',d.pe],['san','SAN',d.san]].map(([k,label,max])=>`<div class="op-master-resource"><div><strong>${label}</strong><span>${d.current[k]} / ${max}</span></div><div class="op-progress ${k}"><i style="width:${Math.min(100,Math.max(0,max?d.current[k]/max*100:0))}%"></i></div><div class="op-quick"><button data-action="quick-resource" data-id="${attr(c.id)}" data-resource="${k}" data-mode="spend" aria-label="Reduzir ${label} de ${attr(c.name)}">−</button><button data-action="quick-resource" data-id="${attr(c.id)}" data-resource="${k}" data-mode="recover" aria-label="Aumentar ${label} de ${attr(c.name)}">+</button></div></div>`).join('')}</div><div class="op-master-extras"><span>Defesa <b>${d.defense}</b></span><span>PE/turno <b>${d.limitPE}</b></span><span>Trilha <b>${esc(c.track||'—')}</b></span></div><button class="op-btn op-btn-subtle" data-action="select" data-id="${attr(c.id)}">Abrir ficha →</button></article>`}).join('')||'<div class="op-empty">Esta campanha ainda não tem fichas. Use “Nova ficha” para adicionar agentes.</div>'}</div>`;
}
function render(){ensure();$('op-storage-label').textContent=shared?'Sincronização ao vivo':'Modo local';$('op-topactions').hidden=view==='campaigns';$('op-mobile-tools').hidden=view==='campaigns';if(view==='campaigns'||!campaign()){view='campaigns';renderCampaigns();return}
 $('op-landing').hidden=true;$('op-workspace').hidden=false;$('op-campaign-bar').hidden=false;$('op-campaign-title').textContent=campaign().name;$('op-master-btn').classList.toggle('active',view==='master');$('op-master-btn').setAttribute('aria-pressed',String(view==='master'));
 $('op-sheets-btn').classList.toggle('active',view==='sheets');$('op-sheets-btn').setAttribute('aria-pressed',String(view==='sheets'));
 renderSidebar();if(view==='wizard'&&draft){$('op-hero').innerHTML='';$('op-tabs').innerHTML='';$('op-content').innerHTML=renderWizard(draft,wizardStep);return}if(view==='master'){renderMaster();return}const c=active();if(!c){$('op-hero').innerHTML='<div class="op-master-heading"><h2>Nenhuma ficha ainda</h2><p>Crie a primeira ficha desta campanha.</p></div>';$('op-tabs').innerHTML='';$('op-content').innerHTML='<div class="op-empty">Use o botão “+ Nova ficha” na lateral para começar.</div>';return}const d=derive(c);renderHero(c,d);
}
async function refreshRemote(){if(!shared||remoteLoading)return;const editing=document.activeElement?.matches?.('input,textarea,select');if(editing){clearTimeout(init.refresh);init.refresh=setTimeout(refreshRemote,1200);return}remoteLoading=true;try{const loaded=await shared.load();state.campaigns=loaded.campaigns;state.characters=loaded.characters.map(restoreCharacterCatalog);ensure();persist();render();}catch(e){syncError(e)}finally{remoteLoading=false}}
async function init(){read();ensure();const cfg=globalThis.ORDEM_SUPABASE_CONFIG;try{shared=await createSharedStore(cfg,()=>{clearTimeout(init.refresh);init.refresh=setTimeout(refreshRemote,160)},s=>{if($('op-save-status'))$('op-save-status').textContent=s});if(shared){const data=await shared.load();state.campaigns=data.campaigns;state.characters=data.characters.map(restoreCharacterCatalog);state.active='';state.activeCampaign='';shared.subscribe();}}catch(e){shared=null;syncError(e);toast('Modo local: Supabase não disponível.')}ready=true;render()}
function renderSidebar(){const c=active();$('character-list').innerHTML=campaignChars().map(item=>`<button class="op-agent ${item.id===c?.id?'is-active':''}" data-action="select" data-id="${attr(item.id)}"><span class="op-agent-avatar">${esc((item.icon||item.name||'?').trim().slice(0,3))}</span><span><strong>${esc(item.name||'Sem nome')}</strong><small>${esc(CLASSES[item.classId]?.title||'Agente')} · NEX ${esc(item.nex)}%</small></span><span class="op-agent-arrow">›</span></button>`).join('')+ (c?`<button class="op-btn op-btn-danger" data-action="delete" title="Excluir ficha selecionada" style="margin:12px 8px;width:calc(100% - 16px)">Excluir ficha de ${esc(c.name||'agente')}</button>`:'')}
function renderHero(c,d){if(tab==='ficha'){$('op-hero').innerHTML='';}const milestones=d.milestones;const faults=validate(c);if(tab!=='ficha')$('op-hero').innerHTML=`<div class="op-hero"><div class="op-hero-back"><div class="op-hero-kicker">DOSSIÊ DE AGENTE <span> / REGISTRO ${esc(c.id.slice(0,8).toUpperCase())}</span></div><div class="op-hero-grid"><div><h2>${esc(c.name||'Novo Agente')}</h2><p>${esc(originOf(c.origin)?.name||'Origem não escolhida')} <span>•</span> ${esc(CLASSES[c.classId]?.title)} ${c.track?'<span>•</span> '+esc(c.track):''}</p></div><div class="op-nex-pill"><small>EXPOSIÇÃO PARANORMAL</small><strong>${esc(c.nex)}<span>%</span></strong></div></div></div><div class="op-meter-grid">${[['pv','PONTOS DE VIDA','♥',d.pv],['pe','PONTOS DE ESFORÇO','✦',d.pe],['san','SANIDADE','◉',d.san]].map(([key,label,icon,max])=>`<div class="op-meter ${key}"><div class="op-meter-heading"><span>${icon} ${label}</span><small>${d.current[key]}/${max}</small></div><div class="op-progress"><i style="width:${Math.min(100,max?d.current[key]/max*100:0)}%"></i></div><div class="op-meter-controls"><button data-action="resource" data-mode="spend" data-resource="${key}" aria-label="Gastar ${label}">−</button><input type="number" min="0" step="1" data-resource-amount="${key}" value="1" aria-label="Quantidade"><button data-action="resource" data-mode="recover" data-resource="${key}" aria-label="Recuperar ${label}">+</button></div></div>`).join('')}</div></div>`;
 const tabs=[['ficha','◈ Ficha completa'],['cadastro','✎ Dados e atributos'],['combate','⚔ Ataques'],['habilidades','✦ Habilidades'],['pericias','✎ Editar perícias'],['progressao','↑ Poderes e NEX'],['inventario','+ Equipamentos'],['rituais','+ Rituais'],['anotacoes','✎ Anotações'],['guia','? Referências']];
 $('op-tabs').innerHTML='<span class="op-dossier-nav-note">Ficha única · use os botões de editar em cada seção</span>';
 $('op-content').innerHTML=(tab==='ficha'?'':`<button class="op-btn op-btn-subtle op-back-sheet" data-action="tab" data-tab="ficha">← Voltar à ficha completa</button>`)+({ficha:()=>renderCompleteSheet(c,d,faults),cadastro:()=>renderSheet(c,d,faults),combate:()=>renderAttacks(c),habilidades:()=>renderAbilities(c),pericias:()=>renderSkills(c,d),progressao:()=>renderProgression(c,d,faults),inventario:()=>renderItems(c,d),rituais:()=>renderRituals(c,d),anotacoes:()=>renderNotes(c),guia:()=>renderGuide()})[tab]();
}
function field(label,html,help=''){return `<label class="op-field"><span>${esc(label)}</span>${html}${help?`<small>${esc(help)}</small>`:''}</label>`}
function inp(path,value,type='text',extra=''){return `<input data-path="${attr(path)}" type="${type}" value="${attr(value??'')}" ${extra}>`}
function sel(path,value,items,placeholder='Selecionar'){return `<select data-path="${attr(path)}">${opts(items,value,placeholder)}</select>`}
function textarea(path,value,rows=5){return `<textarea data-path="${attr(path)}" rows="${rows}">${esc(value||'')}</textarea>`}
function statusCard(faults){return `<article class="op-card op-validation"><div class="op-card-title"><h3>Validação da ficha</h3><small>Regras v${VERSION}</small></div>${faults.errors.length?`<div class="op-warning op-error"><strong>${faults.errors.length} inconsistência(s)</strong><ul>${faults.errors.map(x=>`<li>${esc(x)}</li>`).join('')}</ul></div>`:''}${faults.warnings.length?`<div class="op-warning"><strong>${faults.warnings.length} pendência(s) ou aviso(s)</strong><ul>${faults.warnings.map(x=>`<li>${esc(x)}</li>`).join('')}</ul></div>`:`<p class="op-success">✓ Nenhuma pendência encontrada pelos validadores disponíveis.</p>`}</article>`}
function renderQuickAttributes(c,d){return `<section class="op-card"><h3>Ajustar atributos</h3><p class="op-help">Alterações recalculam automaticamente os valores derivados. Você pode personalizar os atributos independentemente do NEX.</p><div class="op-attrs">${Object.entries(ATTRS).map(([key,label])=>`<label class="op-attr"><small>${key.toUpperCase()}</small><input type="number" min="0" data-path="attrs.${key}" value="${attr(d.attrs[key])}"><span>${esc(label)}</span></label>`).join('')}</div></section>`}
function renderQuickDefense(c,d){return `<section class="op-card"><h3>Ajustar defesa e recursos</h3><div class="op-dossier-stats">${[['DEFESA',d.defense],['ESQUIVA',d.dodge],['BLOQUEIO',cap(d.block)],['PE/TURNO',d.limitPE],['DESLOC.',d.speed+' m'],['CARGA',d.totalSpaces+'/'+d.capacity]].map(([label,value])=>`<div><span>${label}</span><strong>${value}</strong></div>`).join('')}</div><div class="op-form-grid op-class-specific"><div class="op-defense-reset"><p>Valores manuais substituem o cálculo automático até você restaurá-lo.</p>${[['defenseOverride','Defesa'],['dodgeOverride','Esquiva'],['blockOverride','Bloqueio']].map(([k,l])=>`<button type="button" class="op-btn op-btn-subtle" data-action="reset-final-stat" data-stat="${k}">Restaurar ${l} automático</button>`).join('')}</div>${field('Defesa da proteção',inp('armorDefense',c.armorDefense,'number'))}${field('Modificador adicional de Defesa',inp('otherDefense',c.otherDefense,'number'))}${field('Bônus de esquiva',inp('dodgeBonus',c.dodgeBonus||0,'number'))}${field('Bônus de bloqueio',inp('blockBonus',c.blockBonus||0,'number'))}${field('Deslocamento extra (m)',inp('speedBonus',c.speedBonus||0,'number'))}${field('PV extras',inp('extraPV',c.extraPV,'number'))}${field('PE extras',inp('extraPE',c.extraPE,'number'))}${field('SAN extras',inp('extraSAN',c.extraSAN,'number'))}</div><p class="op-help">Esquiva e bloqueio dependem dos treinamentos em Reflexos e Fortitude. Deslocamento depende da carga. Ajuste esses valores por meio das perícias e do inventário; confira modificadores especiais com o mestre.</p></section>`}
function renderSheet(c,d,faults){return `<div class="op-content-grid"><section class="op-panelstack"><article class="op-card"><div class="op-card-title"><div><span class="op-section-eyebrow">CADASTRO</span><h3>Identidade do agente</h3></div><span class="op-tag">NEX ${c.nex}%</span></div><div class="op-form-grid">${field('Nome do agente',inp('name',c.name))}${field('Ícone / emoji',inp('icon',c.icon||'','text','maxlength="12" placeholder="Ex.: 🕵️"'))}${field('Jogador',inp('player',c.player))}${field('Origem',sel('origin',c.origin,ORIGINS.map(o=>o.name)))}${field('Classe',sel('classId',c.classId,Object.entries(CLASSES).map(([k,v])=>({value:k,label:v.title}))))}${field('NEX',sel('nex',c.nex,NEX_STEPS.map(n=>({value:n,label:`${n}%`})),'NEX'))}${field('Trilha',sel('track',c.track,c.nex>=10?TRACKS[c.classId]:[]),c.nex<10?'Disponível no NEX 10%.':'')}${field('Conceito',inp('concept',c.concept))}${field('Prestígio',inp('patentPoints',c.patentPoints,'number','min="0"'))}</div>${c.classId==='combatente'?`<div class="op-form-grid op-class-specific">${field('Perícia principal',sel('choices.combatSkill',c.choices?.combatSkill,['Luta','Pontaria']))}${field('Perícia de resistência',sel('choices.combatResist',c.choices?.combatResist,['Fortitude','Reflexos']))}</div>`:''}<div class="op-help">${esc(CLASSES[c.classId].proficiency)}. Benefício da origem: ${esc(originOf(c.origin)?.power||'Escolha uma origem')}.</div></article><article class="op-card"><div class="op-card-title"><div><span class="op-section-eyebrow">CAPACIDADES</span><h3>Atributos</h3></div><span class="op-tag">${Object.values(d.attrs).reduce((x,y)=>x+y,0)}/${attrBudget(c)} pontos</span></div><div class="op-attrs">${Object.entries(ATTRS).map(([key,label])=>`<label class="op-attr"><small>${key.toUpperCase()}</small><input type="number" min="0" max="5" data-path="attrs.${key}" value="${d.attrs[key]}"><span>${esc(label)}</span></label>`).join('')}</div><div class="op-help">Distribuição inicial: 9 pontos no total, valor máximo inicial de 3. Aumentos adicionais nos NEX 20%, 50%, 80% e 95%. A mudança de atributos recalcula PV, PE, Defesa e carga.</div></article><article class="op-card"><div class="op-card-title"><div><span class="op-section-eyebrow">RESISTÊNCIA</span><h3>Defesa e combate</h3></div></div><div class="op-stat-grid"><div><span>Defesa</span><strong>${d.defense}</strong></div><div><span>Esquiva*</span><strong>${d.dodge}</strong></div><div><span>Bloqueio*</span><strong>${cap(d.block)}</strong></div><div><span>Deslocamento</span><strong>${d.speed}m</strong></div><div><span>Limite PE/turno</span><strong>${d.limitPE}</strong></div><div><span>Carga</span><strong>${d.totalSpaces}/${d.capacity}</strong></div></div><div class="op-form-grid op-class-specific">${field('Defesa da proteção',inp('armorDefense',c.armorDefense,'number'))}${field('Outros modificadores de Defesa',inp('otherDefense',c.otherDefense,'number'))}${field('PV extras (ajuste manual)',inp('extraPV',c.extraPV,'number'))}${field('PE extras (ajuste manual)',inp('extraPE',c.extraPE,'number'))}${field('SAN extras (ajuste manual)',inp('extraSAN',c.extraSAN,'number'))}</div><p class="op-help">* Esquiva e bloqueio são reações, exigem treinamento na perícia correspondente. Os modificadores manuais devem ser conferidos com o livro ou mestre.</p></article></section><aside class="op-panelstack"><article class="op-card op-asidehero"><div class="op-section-eyebrow">PROGRESSÃO</div><h3>O próximo contato</h3><strong>${c.nex===99?'NEX MÁXIMO':`${NEX_STEPS[nexTier(c.nex)]}% NEX`}</strong><p>Trilha: ${esc(c.track||'a definir')}. Rituais: ${d.ritualCircle||'não habilitados pela classe'}. Cada etapa concede os benefícios da classe.</p><button class="op-btn op-btn-primary" data-action="tab" data-tab="progressao">Ver progressão</button></article>${statusCard(faults)}<article class="op-card"><div class="op-section-eyebrow">IDENTIDADE</div><h3>Registro confidencial</h3><p class="op-muted">${esc(c.concept||'Defina o conceito do personagem para registrar seu perfil de investigador.')}</p><button class="op-btn op-btn-danger" data-action="delete">Excluir esta ficha</button></article></aside></div>`}
// One uninterrupted, mobile-first reading surface. Dedicated tabs are for editing, not for viewing.
function overviewTitle(id,kicker,title,tabId,actionLabel){return `<div class="op-overview-heading" id="overview-${id}"><div><span class="op-section-eyebrow">${kicker}</span><h3>${title}</h3></div>${tabId?`<button class="op-btn op-btn-subtle" data-action="tab" data-tab="${tabId}">${actionLabel} ↗</button>`:''}</div>`}
function renderCompleteSheet(c,d,faults){
 const met=(key,label,max)=>`<div class="op-compact-resource ${key}"><div class="op-compact-meter-title"><span>${label}</span><strong>${d.current[key]} / ${max}</strong></div><div class="op-progress"><i style="width:${Math.max(0,Math.min(100, max?100*d.current[key]/max:0))}%"></i></div><div class="op-quick"><button data-action="resource" data-mode="spend" data-resource="${key}" aria-label="Reduzir ${label}">−</button><input type="number" min="1" value="1" data-resource-amount="${key}" aria-label="Quantidade de ${label}"><button data-action="resource" data-mode="recover" data-resource="${key}" aria-label="Aumentar ${label}">+</button></div></div>`;
 const skills=SKILLS.map(s=>{const v=d.skills[s.name];return `<div class="op-dossier-skill"><span>${esc(s.name)} <small>${s.attr.toUpperCase()}</small></span><select data-skill="${attr(s.name)}" aria-label="Treino de ${attr(s.name)}">${[0,1,2,3].map(n=>`<option value="${n}" ${v.grade===n?'selected':''}>${n*5}</option>`).join('')}</select><strong class="op-physical-dice">${diceNotation(d.attrs[s.attr],v.bonus)}</strong></div>`}).join('');
 const weapons=(c.items||[]).map((x,i)=>({...x,_index:i})).filter(isWeaponItem);
 const attacks=(c.attacks||[]).filter(x=>x.name?.trim()).map((a,i)=>`<article class="op-dossier-entry op-combat-weapon"><div class="op-weapon-header"><strong>${esc(a.name)}</strong><span class="op-tag">Ataque manual</span></div><div class="op-item-details op-item-details-always">${[['Dano',a.damage||'—'],['Crítico',a.critical||'—'],['Alcance',a.range||'—'],['Tipo',a.damageType||'—']].map(([k,v])=>`<div><span>${k}</span><b>${esc(v)}</b></div>`).join('')}</div><div class="op-summary-actions"><button class="op-btn op-btn-subtle" data-action="tab" data-tab="combate">Editar ataque</button><button class="op-btn op-btn-danger" data-action="remove-attack" data-i="${i}">Remover</button></div></article>`).join('');
 const weaponsHtml=weapons.map(x=>{const i=x._index,open=expandedItems.has(i),show=expandedWeaponDetails.has(i);
  const details=completeWeaponData(x);const summary=[['Dano',details.damage||'—'],['Crítico',details.critical||'—']];
  const extra=[['Alcance',details.range||'—'],['Tipo de dano',details.damageType||'—'],['Categoria',x.category??0],['Espaços',x.space??1],['Grupo',details.group||'—']];
  return `<article class="op-dossier-entry op-combat-weapon op-weapon-compact">
    <div class="op-weapon-topline"><button class="op-weapon-toggle" data-action="toggle-weapon-details" data-i="${i}" aria-expanded="${show||open}" aria-label="${show||open?'Recolher':'Ver detalhes de'} ${attr(x.name)}"><span class="op-weapon-chevron">${show||open?'⌄':'›'}</span><strong>${esc(x.name)}</strong></button><small>${numeric(x.qty,1)} un.</small><button class="op-btn op-btn-subtle op-weapon-edit" data-action="toggle-item" data-i="${i}">${open?'Concluir':'Editar'}</button></div>
    <div class="op-weapon-key-stats">${summary.map(([k,v])=>`<span><b>${k}</b> ${esc(v)}</span>`).join('')}</div>
    ${show||open?`<div class="op-weapon-more">${extra.map(([k,v])=>`<span><b>${k}</b> ${esc(v)}</span>`).join('')}${x.notes?`<p>${esc(x.notes)}</p>`:''}<button class="op-quick-remove" data-action="remove-item" data-i="${i}">Remover arma da ficha</button></div>`:''}
    ${open?`<div class="op-weapon-edit-grid">${[['name','Nome'],['damage','Dano'],['critical','Crítico'],['range','Alcance'],['damageType','Tipo de dano'],['category','Categoria'],['space','Espaços'],['qty','Quantidade'],['notes','Anotações']].map(([k,l])=>`<label>${l}<input ${['category','space','qty'].includes(k)?'type="number" inputmode="numeric"':'type="text"'} data-collection="items" data-i="${i}" data-key="${k}" value="${attr(details[k]??'')}"></label>`).join('')}</div><button class="op-btn op-btn-danger" data-action="remove-item" data-i="${i}">Remover arma</button>`:''}
  </article>`}).join('');
 const powers=(c.powers||[]).map((x,i)=>({value:x,index:i})).filter(x=>x.value?.trim()&&!((c.abilities||[]).some(a=>clean(a.name)===clean(x.value)))).map(x=>`<div class="op-dossier-entry op-editable-summary"><strong>${esc(x.value)}</strong><button class="op-quick-remove" data-action="remove-power" data-i="${x.index}" aria-label="Remover poder ${attr(x.value)}">Remover</button></div>`).join('');
 const abilities=(c.abilities||[]).map((x,i)=>({...x,_index:i})).filter(x=>x.name?.trim()&&clean(x.name)!==clean(originOf(c.origin)?.power)).map(x=>`<details class="op-dossier-entry op-ability-record"><summary><strong>${esc(x.name)}</strong><small>${esc(x.track||x.group||'Habilidade')}</small></summary>${x.description?`<p>${esc(x.description)}</p>`:'<p class="op-help">Descrição não disponível no catálogo local; preencha em Editar.</p>'}${x.notes?`<p>${esc(x.notes)}</p>`:''}<div class="op-summary-actions"><button class="op-btn op-btn-subtle" data-action="tab" data-tab="habilidades">Editar</button><button class="op-btn op-btn-danger" data-action="remove-ability" data-i="${x._index}">Remover</button></div></details>`).join('');
 const rituals=(c.rituals||[]).map((r,i)=>({...r,_index:i})).filter(r=>r.name?.trim()).map(r=>{
  const i=r._index,open=expandedRituals.has(i),editing=editingRituals.has(i);
  const ritualStats=ritualDamageData(r);const variants=[['Normal',ritualStats.damage],['Discente',ritualStats.discenteDamage],['Verdadeiro',ritualStats.verdadeiroDamage]].filter(([,value])=>String(value||'').trim());
  const fields=[['name','Nome'],['element','Elemento'],['circle','Círculo'],['damage','Dano normal'],['discenteDamage','Dano discente'],['verdadeiroDamage','Dano verdadeiro'],['casting','Execução'],['range','Alcance'],['target','Alvo'],['area','Área'],['duration','Duração'],['resistance','Resistência'],['note','Anotações']];
  return `<article class="op-dossier-entry op-ritual-compact"><div class="op-ritual-topline"><button class="op-ritual-toggle" data-action="toggle-ritual-details" data-i="${i}" aria-expanded="${open}" aria-label="${open?'Recolher':'Ver detalhes de'} ${attr(r.name)}"><span class="op-weapon-chevron">${open?'⌄':'›'}</span><strong>${esc(r.name)}</strong></button><button class="op-btn op-btn-subtle op-ritual-edit" data-action="toggle-ritual-edit" data-i="${i}">${editing?'Concluir':'Editar'}</button></div>
  <small>${esc(r.element||'Elemento a definir')} · ${numeric(r.circle,1)}º círculo · ${RITUAL_COST[r.circle]||'?'} PE</small>
  <div class="op-ritual-damage">${r.needsCatalogSelection?'<span class="op-ritual-no-damage">Escolha o elemento para associar ao catálogo.</span>':''}${variants.length?variants.map(([label,value])=>`<span><b>${label}</b><strong>${esc(value)}</strong></span>`).join(''):'<span class="op-ritual-no-damage">Dano: não cadastrado</span>'}</div>
  ${open?`<div class="op-ritual-extra">${[['Execução',r.casting],['Alcance',r.range],['Alvo',r.target],['Área',r.area],['Duração',r.duration],['Resistência',r.resistance]].filter(([,v])=>v).map(([label,v])=>`<span><b>${label}:</b> ${esc(v)}</span>`).join('')}${r.needsCatalogSelection?'<p class="op-help">Este ritual existe em mais de um elemento. Use Editar para selecionar o elemento correto.</p>':''}${r.summary?`<p>${esc(r.summary)}</p>`:''}${r.note?`<p>${esc(r.note)}</p>`:''}</div>`:''}
  ${editing?`<div class="op-ritual-edit-grid">${fields.map(([key,label])=>`<label>${label}<input type="${key==='circle'?'number':'text'}" data-collection="rituals" data-i="${i}" data-key="${key}" value="${attr(r[key]??'')}"></label>`).join('')}<button class="op-btn op-btn-danger" data-action="remove-ritual" data-i="${i}">Remover ritual da ficha</button></div>`:''}</article>`;
 }).join('');
 const inventory=(c.items||[]).map((x,i)=>({...x,_index:i})).filter(x=>!isWeaponItem(x)&&x.name?.trim()).map(x=>{const i=x._index;const open=expandedItems.has(i);return `<article class="op-dossier-entry op-inventory-item"><div class="op-weapon-header"><strong>${esc(x.name)}</strong><small>${numeric(x.qty,1)} un. · ${esc(x.type||'Outro')} · ${numeric(x.space,1)} espaço(s)</small><button class="op-btn op-btn-subtle op-weapon-edit" data-action="toggle-item" data-i="${i}">${open?'Fechar edição':'Editar'}</button></div>${x.notes?`<p class="op-item-note">${esc(x.notes)}</p>`:''}${open?`<div class="op-weapon-edit-grid">${[['name','Nome'],['type','Tipo'],['category','Categoria'],['space','Espaços'],['qty','Quantidade'],['notes','Anotações']].map(([k,l])=>`<label>${l}<input ${['category','space','qty'].includes(k)?'type="number" inputmode="numeric"':'type="text"'} data-collection="items" data-i="${i}" data-key="${k}" value="${attr(x[k]??'')}"></label>`).join('')}<button class="op-quick-remove" data-action="remove-item" data-i="${i}">Remover item da ficha</button></div>`:''}</article>`}).join('');
 const section=(id,title,edit,body)=>`<section class="op-dossier-section" id="overview-${id}"><div class="op-dossier-heading"><h3>${title}</h3><button class="op-btn op-btn-subtle" data-action="tab" data-tab="${edit}" aria-label="Editar ${title}">+ Editar</button></div>${body||'<p class="op-dossier-empty">Ainda não registrado.</p>'}</section>`;
 return `<div class="op-dossier-jumps" aria-label="Ir para seção">${[['atributos','Atributos'],['pericias','Perícias'],['combate','Combate'],['rituais','Rituais'],['habilidades','Habilidades'],['inventario','Inventário']].map(([x,y])=>`<a href="#overview-${x}">${y}</a>`).join('')}</div>
 <div class="op-dossier-grid"><div class="op-dossier-left"><section class="op-dossier-identity"><div class="op-dossier-avatar">${esc((c.icon||'🕵️').slice(0,3))}</div><div><small>PERSONAGEM · NEX ${c.nex}%</small><h2>${esc(c.name)}</h2><p>${esc(c.player||'Jogador não informado')} · ${esc(CLASSES[c.classId]?.title)} · ${esc(c.origin||'Sem origem')}</p><span>${esc(c.track||'Trilha não escolhida')}</span></div><button class="op-btn op-btn-subtle" data-action="tab" data-tab="cadastro" title="Editar identidade">✎</button></section>
 ${section('atributos','Atributos','atributos-rapidos',`<div class="op-dossier-attrs op-dossier-attrs-edit">${Object.entries(ATTRS).map(([key,label])=>`<label><small>${key.toUpperCase()}</small><input type="number" inputmode="numeric" min="0" max="99" data-path="attrs.${key}" value="${d.attrs[key]}" aria-label="Editar ${attr(label)} diretamente"><span>${esc(label)}</span></label>`).join('')}</div><p class="op-inline-help">Toque no número para editar. Salva ao confirmar.</p>`)}
 <div class="op-dossier-meters">${met('pv','VIDA',d.pv)}${met('san','SANIDADE',d.san)}${met('pe','ESFORÇO',d.pe)}</div>
 <section class="op-dossier-section"><div class="op-dossier-heading"><h3>Defesa e resistência</h3><button class="op-btn op-btn-subtle" data-action="tab" data-tab="defesa-rapida">Editar</button></div><div class="op-dossier-stats">${[['DEFESA',d.defense,'defenseOverride'],['ESQUIVA',d.dodge,'dodgeOverride'],['BLOQUEIO',d.block,'blockOverride']].map(([l,v,k])=>`<label class="op-direct-stat"><span>${l}</span><input type="number" inputmode="numeric" data-final-stat="${k}" value="${v}" aria-label="Editar ${l} diretamente" title="Valor final editável"><small>${c[k]===null||c[k]===undefined?'Automático':'Manual'}</small></label>`).join('')}${[['PE/TURNO',d.limitPE],['DESLOC.',d.speed+' m'],['CARGA',d.totalSpaces+'/'+d.capacity]].map(([l,v])=>`<div><span>${l}</span><strong>${v}</strong></div>`).join('')}</div><p class="op-inline-help">Toque em Defesa, Esquiva ou Bloqueio para ajustar o valor final. Use Editar para retornar aos cálculos automáticos e ajustar os bônus. ${esc(CLASSES[c.classId]?.proficiency||'')}</p></section></div>
 <div class="op-dossier-center">${section('pericias','Perícias','pericias',`<p class="op-help op-dice-explainer">Dados para jogar presencialmente · resultado maior (ou menor quando indicado).</p><div class="op-dossier-skills">${skills}</div>`)}</div>
 <div class="op-dossier-right">${section('combate','Combate · armas e ataques','combate',weaponsHtml+attacks+`<button class="op-btn op-btn-primary op-open-catalog" data-action="open-weapon-catalog">+ Adicionar arma</button>`)}${section('rituais','Rituais','rituais',rituals+`<button class="op-btn op-btn-primary op-open-catalog" data-action="open-ritual-catalog">+ Adicionar ritual</button>`)}${section('habilidades','Habilidades e poderes','habilidades',`<div class="op-dossier-entry"><strong>${esc(originOf(c.origin)?.power||'Origem não definida')}</strong><small>Poder de origem · ${esc(c.origin)}</small></div>${c.track?`<div class="op-dossier-entry"><strong>Trilha: ${esc(c.track)}</strong><small>Habilidades da trilha são liberadas conforme NEX.</small></div>`:''}${powers}${abilities}<button class="op-btn op-btn-primary op-open-catalog" data-action="open-ability-catalog">+ Adicionar habilidade</button>`)}${section('inventario','Inventário','inventario',`<p class="op-help">Carga ${d.totalSpaces}/${d.capacity} · ${esc(d.patent.name)}</p>${inventory}<label class="op-inventory-notes">Anotações de inventário<textarea data-path="inventoryNotes" rows="4" placeholder="Munição, consumíveis, pistas, itens pessoais, observações...">${esc(c.inventoryNotes||'')}</textarea></label><button class="op-btn op-btn-primary op-open-catalog" data-action="open-equipment-catalog">+ Adicionar item</button>`)}${section('historia','Descrição e notas','anotacoes',`<p class="op-summary-prose">${esc(c.background||c.concept||'Sem histórico.')}</p><p class="op-summary-prose">${esc(c.notes||'')}</p>`)}</div></div>
 ${faults.errors.length?`<div class="op-dossier-alert">⚠ ${faults.errors.length} inconsistência(s) nas regras. <button data-action="tab" data-tab="cadastro">Conferir</button></div>`:''}`;
}
function catalogSelect(group,label){
 const list=group==='rituals'?RITUALS:group==='attacks'?WEAPONS.filter(x=>x.type==='Arma'):CATALOG;
 return `<div class="op-catalog-picker"><label>${esc(label)}<input type="search" data-filter-catalog placeholder="Filtrar pelo nome…" autocomplete="off"><select data-catalog-add="${attr(group)}"><option value="">Pesquisar no catálogo: selecione um registro…</option>${list.map(x=>`<option value="${attr(x.id)}">${esc(x.name)}${x.element?` · ${esc(x.element)} · ${x.circle}º`:''}${x.damage?` · ${esc(x.damage)}`:''}${x.type&&group==='items'?` · ${esc(x.type)}`:''}</option>`).join('')}</select></label><small>Os dados iniciais são preenchidos pelo catálogo e podem ser editados. Confira requisitos e exceções no livro v1.2.</small></div>`;
}
function renderAttacks(c){const attacks=c.attacks||[];return `<section class="op-card"><h3>Armas equipadas</h3><p class="op-help">Armas adicionadas aqui aparecem no Combate e são contabilizadas na carga. Modifique suas estatísticas direto na ficha.</p>${(c.items||[]).filter(isWeaponItem).map(x=>`<p class="op-combat-editor-line"><strong>${esc(x.name)}</strong> · ${esc(x.damage||'—')} · Crítico ${esc(x.critical||'—')} · ${esc(x.range||'—')}</p>`).join('')}<button class="op-btn op-btn-primary" data-action="open-weapon-catalog">+ Buscar arma no catálogo</button></section><section class="op-card"><h3>Ataques personalizados</h3><p class="op-help">Use apenas para ataques que não estão registrados como armas.</p><div class="op-attack-edit-list"><div class="op-card-title"><h3>Ataques registrados</h3><span class="op-tag">${attacks.length} ataques</span></div><p class="op-help">Cadastre armas e ataques para consulta rápida na ficha. Consulte o dano e o crítico da arma para realizar a rolagem presencialmente.</p>${attacks.map((a,i)=>`<div class="op-attack-editor"><label>ATAQUE<input data-collection="attacks" data-i="${i}" data-key="name" value="${attr(a.name||'')}" placeholder="Ex.: Revólver"></label><label>DANO<input data-collection="attacks" data-i="${i}" data-key="damage" value="${attr(a.damage||'')}" placeholder="Ex.: 2d6"></label><label>CRÍTICO<input data-collection="attacks" data-i="${i}" data-key="critical" value="${attr(a.critical||'')}" placeholder="Ex.: 19/x3"></label><label>OBSERVAÇÕES<input data-collection="attacks" data-i="${i}" data-key="notes" value="${attr(a.notes||'')}"></label><button class="op-btn op-btn-danger" data-action="remove-attack" data-i="${i}">Excluir ataque</button></div>`).join('')}<button class="op-btn op-btn-primary" data-action="add-attack">+ Ataque personalizado</button></div></section>`}
function renderAbilities(c){return `<section class="op-panelstack"><article class="op-card"><h3>Habilidades e poderes</h3><p class="op-help">Selecione poderes de classe, trilha, origem ou paranormais no catálogo. Edite os dados e suas observações livremente; as escolhas não são aplicadas automaticamente aos cálculos.</p><button class="op-btn op-btn-primary op-open-catalog" data-action="open-ability-catalog">+ Catálogo de habilidades</button>${(c.abilities||[]).map((a,i)=>`<div class="op-ability-editor"><label>HABILIDADE<input data-collection="abilities" data-i="${i}" data-key="name" value="${attr(a.name||'')}" placeholder="Nome da habilidade"></label><label>CATEGORIA<input data-collection="abilities" data-i="${i}" data-key="group" value="${attr(a.group||'')}" placeholder="Classe, trilha, origem..."></label><label>TRILHA<input data-collection="abilities" data-i="${i}" data-key="track" value="${attr(a.track||'')}" placeholder="Opcional"></label><label>EFEITO / DESCRIÇÃO<textarea data-collection="abilities" data-i="${i}" data-key="description" rows="3" placeholder="Efeito ou resumo do livro">${esc(a.description||'')}</textarea></label><label>OBSERVAÇÕES<textarea data-collection="abilities" data-i="${i}" data-key="notes" rows="2" placeholder="Modificações ou efeitos da mesa">${esc(a.notes||'')}</textarea></label><button class="op-btn op-btn-danger" data-action="remove-ability" data-i="${i}">Remover</button></div>`).join('')}<button class="op-btn op-btn-subtle" data-action="add-ability">+ Habilidade personalizada</button></article></section>`}

function renderSkills(c,d){return `<section class="op-panelstack"><article class="op-card"><div class="op-card-title"><div><span class="op-section-eyebrow">TESTES E PERÍCIAS</span><h3>Quadro de treinamento</h3></div><span class="op-tag">${d.manualTraining}/${d.extraTraining} escolhas livres</span></div><p class="op-help">Os dados dependem do atributo; usa-se o maior d20 (ou o menor de 2d20 se o atributo for zero). Bônus por grau: +0, +5, +10, +15. As perícias concedidas pela origem/classe são automáticas.</p><div class="op-skills-table"><div class="op-skills-header"><span>PERÍCIA</span><span>ATR.</span><span>GRAU</span><span>BÔNUS</span><span>DADOS FÍSICOS</span></div>${SKILLS.map(s=>{const got=d.skills[s.name];const fixed=effectiveGrade({...c,skills:{}},s.name)>0;return `<div class="op-skillrow"><span><strong>${esc(s.name)}</strong><small>${[s.requiresTraining?'treinada':'',s.carga?'carga':'',s.kit?'kit':''].filter(Boolean).join(' · ')}</small></span><span class="op-attribute-mark">${s.attr.toUpperCase()}</span><select data-skill="${attr(s.name)}" aria-label="Grau de ${attr(s.name)}"><option value="0" ${got.grade===0?'selected':''}>Leigo (+0)</option><option value="1" ${got.grade===1?'selected':''}>Treinado (+5)</option><option value="2" ${got.grade===2?'selected':''}>Veterano (+10)</option><option value="3" ${got.grade===3?'selected':''}>Expert (+15)</option></select><span class="op-bonus">${cap(got.bonus)}</span><span class="op-physical-dice">${diceNotation(d.attrs[s.attr],got.bonus)}</span></div>`}).join('')}</div><p class="op-help">Role os dados indicados presencialmente; nenhuma rolagem é feita pelo site.</p></article></section>`}
function renderProgression(c,d,faults){const steps=d.milestones;return `<div class="op-content-grid"><section class="op-panelstack"><article class="op-card"><div class="op-card-title"><div><span class="op-section-eyebrow">PROGRESSÃO OFICIAL</span><h3>Etapas de NEX</h3></div><span class="op-tag">Etapa ${steps.tier}/20</span></div><div class="op-nex-grid">${NEX_STEPS.map(n=>`<button class="op-nex-chip ${c.nex===n?'active':''} ${c.nex>n?'passed':''}" data-action="nex" data-nex="${n}"><strong>${n}%</strong><small>${n===10?'Trilha':n===20||n===50||n===80||n===95?'Atributo':n===35||n===70?'Perícias':n===40||n===65||n===99?'Trilha':n===15||n===30||n===45||n===60||n===75||n===90?'Poder':'Avanço'}</small></button>`).join('')}</div></article><article class="op-card"><div class="op-card-title"><div><span class="op-section-eyebrow">ESCOLHAS</span><h3>Poderes de classe</h3></div><span class="op-tag">${(c.powers||[]).filter(p=>p?.trim()).length}/${steps.powerNex.length}</span></div><p class="op-help">Registre os nomes dos poderes escolhidos após conferir pré-requisitos no PDF. A aplicação automática de todos os poderes ainda não está implementada.</p>${steps.powerNex.length?steps.powerNex.map((n,i)=>`<label class="op-inline-choice"><span>NEX ${n}%</span><input data-power-index="${i}" value="${attr(c.powers?.[i]||'')}" placeholder="Nome do poder escolhido"></label>`).join(''):'<p class="op-muted">O primeiro poder de classe é recebido no NEX 15%.</p>'}</article></section><aside class="op-panelstack"><article class="op-card"><div class="op-section-eyebrow">MARCOS</div><h3>Seus benefícios</h3><div class="op-milestone-list">${[['Aumentos de atributo',steps.attrCount],['Poderes de classe',steps.powerNex.length],['Habilidades de trilha',steps.trailNex.length],['Treinamento avançado',steps.gradeNex.length],['Versatilidade',steps.versatility?'Disponível':'Pendente']].map(([a,b])=>`<div><span>${a}</span><strong>${b}</strong></div>`).join('')}</div><p class="op-help">As habilidades automáticas de trilha são liberadas nos NEX 10%, 40%, 65% e 99%. A escolha de trilha pode ser feita na ficha inicial.</p></article>${statusCard(faults)}</aside></div>`}
function renderItems(c,d){const rows=(c.items||[]).map((x,i)=>({...x,_index:i})).filter(x=>!isWeaponItem(x));return `<section class="op-panelstack"><article class="op-card"><h3>Itens e equipamentos (sem armas)</h3><p class="op-help">O arsenal de armas fica em Combate. Aqui ficam proteções, acessórios, munições, consumíveis e itens gerais. A carga inclui todos os equipamentos.</p><p class="op-help">Carga: ${d.totalSpaces}/${d.capacity} · Patente: ${esc(d.patent.name)}</p>${rows.map(x=>`<div class="op-gear-edit"><label>Nome<input data-collection="items" data-i="${x._index}" data-key="name" value="${attr(x.name||'')}"></label><label>Tipo<input data-collection="items" data-i="${x._index}" data-key="type" value="${attr(x.type||'Outro')}"></label><label>Espaços<input type="number" data-collection="items" data-i="${x._index}" data-key="space" value="${numeric(x.space,1)}"></label><label>Quantidade<input type="number" data-collection="items" data-i="${x._index}" data-key="qty" value="${numeric(x.qty,1)}"></label><label>Notas<input data-collection="items" data-i="${x._index}" data-key="notes" value="${attr(x.notes||'')}"></label><button class="op-btn op-btn-danger" data-action="remove-item" data-i="${x._index}">Remover</button></div>`).join('')}<label class="op-inventory-notes">Notas livres de inventário<textarea data-path="inventoryNotes" rows="6">${esc(c.inventoryNotes||'')}</textarea></label><button class="op-btn op-btn-primary" data-action="open-equipment-catalog">+ Catálogo de itens</button><button class="op-btn op-btn-subtle" data-action="add-item">+ Item personalizado</button></article></section>`}
function renderRituals(c,d){const rituals=c.rituals||[];return `<section class="op-panelstack"><article class="op-card"><div class="op-card-title"><div><span class="op-section-eyebrow">O OUTRO LADO</span><h3>Rituais conhecidos</h3></div><span class="op-tag">${d.ritualCircle?`até ${d.ritualCircle}º círculo pela classe`:'Aprendizado especial'}</span></div><p class="op-help">Custos básicos: 1º = 1 PE; 2º = 3 PE; 3º = 6 PE; 4º = 10 PE. Outros requisitos, aprimoramentos e limites precisam ser consultados no livro. A ficha registra rituais cadastrados pelo usuário, sem reproduzir o catálogo integral.</p><div class="op-ritual-grid">${rituals.map((r,i)=>`<div class="op-ritual"><div class="op-ritual-top"><input aria-label="Nome do ritual" data-collection="rituals" data-i="${i}" data-key="name" value="${attr(r.name||'')}" placeholder="Nome do ritual"><button class="op-remove" data-action="remove-ritual" data-i="${i}" title="Remover ritual">×</button></div><div class="op-ritual-fields"><label>ELEMENTO<select data-collection="rituals" data-i="${i}" data-key="element">${opts(['Sangue','Morte','Conhecimento','Energia','Medo'],r.element,'Elemento')}</select></label><label>CÍRCULO<select data-collection="rituals" data-i="${i}" data-key="circle">${opts([1,2,3,4].map(x=>({value:x,label:`${x}º círculo`})),r.circle,'Círculo')}</select></label><button class="op-btn op-btn-roll" data-action="cast" data-i="${i}">Gastar ${RITUAL_COST[r.circle]||'?'} PE</button></div><textarea data-collection="rituals" data-i="${i}" data-key="note" placeholder="Alcance, duração, condições ou anotações pessoais (sem transcrever o livro)...">${esc(r.note||'')}</textarea></div>`).join('')}${!rituals.length?'<p class="op-muted">Nenhum ritual registrado. Ocultistas iniciam com 3 rituais de 1º círculo para escolher no livro.</p>':''}</div><button class="op-btn op-btn-primary op-open-catalog" data-action="open-ritual-catalog">✦ Explorar catálogo de rituais</button><button class="op-btn op-btn-primary" data-action="add-ritual">+ Ritual personalizado</button></article></section>`}
function renderNotes(c){return `<section class="op-panelstack"><article class="op-card"><div class="op-card-title"><div><span class="op-section-eyebrow">RELATÓRIOS DE CAMPO</span><h3>História e observações</h3></div></div>${field('Histórico do agente',textarea('background',c.background,8))}${field('Anotações da missão',textarea('notes',c.notes,12))}<p class="op-help">Salvamento automático ${shared?'no Supabase compartilhado':'neste navegador'}. Exporte um backup JSON regularmente.</p></article></section>`}
function renderGuide(){const rows=[['Criação','p. 13–15','Atributos: 9 pontos de soma inicial, máximo 3, origem e classe.'],['Origens','p. 16–21','Perícias automáticas e poder de origem.'],['Classes','p. 22–35','Base de PV, PE e SAN, NEX, trilhas e poderes.'],['Perícias','p. 39–41','Rolagem de d20, grau de treinamento, perícias e limitações.'],['Equipamento','p. 51–53','Patente, categorias, carga e sobrecarga.'],['Combate','p. 83–89','Defesa, ações, reações, bloqueio e esquiva.'],['Rituais','p. 119','Custo de PE por círculo e regras de conjuração.']];return `<section class="op-panelstack"><article class="op-card"><div class="op-card-title"><div><span class="op-section-eyebrow">FONTE MECÂNICA</span><h3>Guia de implementação</h3></div><span class="op-tag">PDF v${VERSION}</span></div><p class="op-help">Este programa implementa apenas mecânicas documentadas. As referências usam a numeração impressa no livro, não o número absoluto de página do arquivo PDF.</p><div class="op-reference-list">${rows.map(([name,page,detail])=>`<div><strong>${esc(name)}</strong><small>${esc(page)}</small><p>${esc(detail)}</p></div>`).join('')}</div><h3>Funcionalidades preservadas no repositório</h3><p class="op-muted">O código original de mesa virtual, combate, mestre, documentos e integração em tempo real permanece no clone para migração posterior. A interface legada encontra-se em <code>legacy.html</code>, desativada até receber um backend isolado.</p><h3>Limites atuais</h3><p class="op-muted">Campanhas e painel do mestre já estão disponíveis; a mesa integrada e a aplicação automática de todos os poderes/rituais ainda não foram migrados. Não suponha que os resultados manuais substituam a arbitragem do mestre.</p></article></section>`}
function setPath(obj,path,value){const parts=path.split('.');let n=obj;while(parts.length>1){const k=parts.shift();n[k]??={};n=n[k]}n[parts[0]]=value;}
function onEdit(e){const target=e.target;
 if(target.dataset.catalogAdd){
  const group=target.dataset.catalogAdd,id=target.value;if(!id)return;
  const item=createFromCatalog(group,id);if(!item)return;
  const c=active();if(!c)return;c[group]??=[];c[group].push(item);commit();toast(`Adicionado: ${item.name}`);return;
 }
 if(draft&&view==='wizard'){
  if(target.dataset.wizard){const path=target.dataset.wizard;let v=target.value;if(path.startsWith('attrs.')||path==='nex')v=numeric(v);if(path==='classId'){draft.classId=v;draft.track='';draft.powers=[];draft.rituals=[];draft.skills={};draft.choices={combatSkill:null,combatResist:null}}else if(path==='nex'){draft.nex=v;draft.track=''}else setPath(draft,path,v);if(['origin','classId','nex'].includes(path))render();return}
  if(target.dataset.wizardCatalog){
   const id=target.value;const entry=createFromCatalog('rituals',id);
   if(entry){draft.rituals??=[];draft.rituals.push(entry);render();}
   return;
  }
  if(target.dataset.wizardSkill){const name=target.dataset.wizardSkill;draft.skills??={};const grade=numeric(target.value);draft.freeformSkills=true;draft.skills[name]=grade;const tip=document.querySelector('.op-wiz-skill-count');if(tip)tip.textContent=`Treinamentos livres: ${derive(draft).manualTraining} / ${derive(draft).extraTraining}`;return}
  if(target.dataset.wizardPower!=null){draft.powers[numeric(target.dataset.wizardPower)]=target.value;return}
  if(target.dataset.wizardAbility!=null){const i=numeric(target.dataset.wizardAbility),key=target.dataset.key;if(draft.abilities?.[i])draft.abilities[i][key]=target.value;return}
  if(target.dataset.wizardRitual!=null){const i=numeric(target.dataset.wizardRitual),key=target.dataset.key;if(draft.rituals[i])draft.rituals[i][key]=key==='circle'?numeric(target.value):target.value;return}
 }
 const c=active();if(target.dataset.finalStat){if(!c)return;c[target.dataset.finalStat]=numeric(target.value);commit();return}
 if(target.dataset.path){let value=target.value;const path=target.dataset.path;if(path==='nex'){try{const next=changeNex(c,numeric(value));Object.assign(c,next)}catch(err){toast(err.message);return}}else if(path==='classId'){c.classId=value;c.track='';c.powers=[];c.rituals=[];c.current={pv:null,pe:null,san:null};c.skills={}}else if(path==='origin'){c.origin=value;c.current={pv:null,pe:null,san:null};c.skills={}}else{if(target.type==='number')value=numeric(value);setPath(c,path,value)}commit();return}
 if(target.dataset.skill){const grade=numeric(target.value);const key=target.dataset.skill;c.freeformSkills=true;c.skills??={};c.skills[key]=grade;commit();return}
 if(target.dataset.powerIndex!=null){c.powers??=[];c.powers[numeric(target.dataset.powerIndex)]=target.value;commit();return}
 if(target.dataset.collection){const collection=target.dataset.collection,i=numeric(target.dataset.i),key=target.dataset.key;if(!Array.isArray(c[collection])||!c[collection][i])return;c[collection][i][key]=target.type==='number'||['circle','category','space','qty'].includes(key)?numeric(target.value):target.value;commit()}
}

function ritualModalHtml(){
 const filtered=RITUALS.filter(x=>(ritualModal.element==='Todos'||x.element===ritualModal.element)&&(!ritualModal.circle||x.circle===ritualModal.circle)&&(`${x.name} ${x.element} ${x.summary||''}`).normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLocaleLowerCase('pt-BR').includes(ritualModal.search.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLocaleLowerCase('pt-BR')));
 return `<div class="op-modal-scrim" data-modal-overlay><section class="op-ritual-modal" role="dialog" aria-modal="true" aria-label="Adicionar rituais"><header class="op-modal-head"><div><small>O OUTRO LADO · CATÁLOGO V1.2</small><h2>Adicionar rituais</h2></div><button class="op-modal-close" data-action="close-ritual-catalog" aria-label="Fechar">×</button></header><div class="op-modal-toolbar"><div class="op-modal-elements">${['Todos','CONHECIMENTO','ENERGIA','MORTE','SANGUE','MEDO'].map(n=>`<button class="${ritualModal.element===n?'active':''}" data-action="ritual-filter-element" data-element="${n}">${n==='Todos'?'Todos':n.charAt(0)+n.slice(1).toLowerCase()}</button>`).join('')}</div><div class="op-modal-circles">${[0,1,2,3,4].map(n=>`<button class="${ritualModal.circle===n?'active':''}" data-action="ritual-filter-circle" data-circle="${n}">${n?n+'º círculo':'Todos'}</button>`).join('')}</div><input id="op-ritual-search" type="search" data-ritual-search placeholder="⌕ Buscar ritual por nome ou efeito" value="${attr(ritualModal.search)}" autocomplete="off"><small>${filtered.length} rituais encontrados · clique para ver detalhes</small></div><div class="op-modal-results">${filtered.map(x=>{const expanded=ritualModal.expanded===x.id;return `<article class="op-modal-ritual"><div class="op-modal-ritual-row"><button data-action="ritual-expand" data-id="${attr(x.id)}" aria-expanded="${expanded}" class="op-modal-expand"><span class="op-modal-chevron">${expanded?'⌄':'›'}</span><strong>${esc(x.name)}</strong><small>${esc(x.element)} · ${x.circle}º</small></button><button class="op-btn op-btn-primary op-add-ritual" data-action="ritual-pick" data-id="${attr(x.id)}" aria-label="Adicionar ${attr(x.name)}">+</button></div>${expanded?`<div class="op-modal-detail"><span class="op-tag">${esc(x.element)} · ${x.circle}º círculo</span><p>${esc(x.summary||'Consulte os efeitos e aprimoramentos na página indicada do livro de regras.')}</p><div class="op-modal-metadata">${[['Dano normal',ritualDamageData(x).damage],['Dano discente',ritualDamageData(x).discenteDamage],['Dano verdadeiro',ritualDamageData(x).verdadeiroDamage],['Execução',x.casting],['Alcance',x.range],['Alvo',x.target],['Área',x.area],['Duração',x.duration],['Resistência',x.resistance]].filter(([,v])=>v).map(([label,v])=>`<span><b>${label}</b> ${esc(v)}</span>`).join('')}</div><small>Referência: Ordem Paranormal RPG v1.2, página ${x.detailPage||x.page}. Resumo para consulta; efeitos completos e aprimoramentos devem ser conferidos no livro.</small><button class="op-btn op-btn-subtle" data-action="ritual-pick" data-id="${attr(x.id)}">+ Adicionar à ficha</button></div>`:''}</article>`}).join('')||'<p class="op-empty">Nenhum ritual corresponde aos filtros.</p>'}</div><footer class="op-modal-footer"><span>Informações resumidas; consulte o livro para regras completas.</span><button class="op-btn op-btn-subtle" data-action="close-ritual-catalog">Fechar</button></footer></section></div>`;
}
function refreshRitualModal(preserveFocus=false){let node=document.getElementById('op-ritual-modal-root');if(!node){node=document.createElement('div');node.id='op-ritual-modal-root';document.body.appendChild(node)}const scroll=node.querySelector?.('.op-modal-results')?.scrollTop||0;node.innerHTML=ritualModal.open?ritualModalHtml():'';const results=node.querySelector?.('.op-modal-results');if(results)results.scrollTop=scroll;document.body.classList.toggle('op-modal-open',ritualModal.open||equipmentModal.open||abilityModal.open||!!editorModal);if(preserveFocus){const input=document.getElementById('op-ritual-search');input?.focus();input?.setSelectionRange(input.value.length,input.value.length)}}

function equipmentModalHtml(){
 const source=CATALOG.filter(x=>equipmentModal.mode==='weapons'?isWeaponItem(x):!isWeaponItem(x));
 const types=['Todos',...new Set(source.map(x=>x.type).filter(Boolean))];
 const filtered=source.filter(x=>(equipmentModal.type==='Todos'||x.type===equipmentModal.type)&&clean(`${x.name} ${x.type} ${x.group||''}`).includes(clean(equipmentModal.search)));
 return `<div class="op-modal-scrim" data-modal-overlay><section class="op-ritual-modal op-equipment-modal" role="dialog" aria-modal="true" aria-label="Adicionar equipamentos"><header class="op-modal-head"><div><small>ARSENAL · CATÁLOGO V1.2</small><h2>${equipmentModal.mode==='weapons'?'Adicionar armas':'Adicionar itens e equipamentos'}</h2></div><button class="op-modal-close" data-action="close-equipment-catalog" aria-label="Fechar">×</button></header><div class="op-modal-toolbar"><div class="op-modal-elements">${types.map(t=>`<button class="${equipmentModal.type===t?'active':''}" data-action="equipment-filter-type" data-type="${attr(t)}">${esc(t)}</button>`).join('')}</div><input id="op-equipment-search" type="search" data-equipment-search placeholder="Buscar por nome, tipo ou grupo" value="${attr(equipmentModal.search)}" autocomplete="off"><small>${filtered.length} equipamentos · toque para ver os detalhes</small></div><div class="op-modal-results">${filtered.map(x=>{const expanded=equipmentModal.expanded===x.id;return `<article class="op-modal-ritual"><div class="op-modal-ritual-row"><button data-action="equipment-expand" data-id="${attr(x.id)}" aria-expanded="${expanded}" class="op-modal-expand"><span class="op-modal-chevron">${expanded?'⌄':'›'}</span><strong>${esc(x.name)}</strong><small>${esc(x.type||'Item')} · Cat. ${x.category??0}</small></button><button class="op-btn op-btn-primary op-add-ritual" data-action="equipment-pick" data-id="${attr(x.id)}" aria-label="Adicionar ${attr(x.name)}">+</button></div>${expanded?`<div class="op-modal-detail"><span class="op-tag">${esc(x.type||'Item')}</span><div class="op-modal-metadata">${[['Dano',x.damage],['Crítico',x.critical],['Alcance',x.range],['Tipo de dano',x.damageType],['Categoria',x.category],['Espaços',x.space],['Grupo',x.group]].filter(([,v])=>v!==undefined&&v!==null&&v!=='').map(([label,v])=>`<span><b>${label}</b> ${esc(v)}</span>`).join('')}</div><small>Referência: Ordem Paranormal RPG v1.2, página ${esc(x.page||'a consultar')}. Estatísticas resumidas.</small><button class="op-btn op-btn-subtle" data-action="equipment-pick" data-id="${attr(x.id)}">+ Adicionar à ficha</button></div>`:''}</article>`}).join('')||'<p class="op-empty">Nenhum item encontrado.</p>'}</div><footer class="op-modal-footer"><span>Os dados adicionados podem ser editados depois.</span><button class="op-btn op-btn-subtle" data-action="close-equipment-catalog">Fechar</button></footer></section></div>`;
}
function refreshEquipmentModal(focus=false){let node=$('op-equipment-modal-root');if(!node){node=document.createElement('div');node.id='op-equipment-modal-root';document.body.appendChild(node)}const scroll=node.querySelector?.('.op-modal-results')?.scrollTop||0;node.innerHTML=equipmentModal.open?equipmentModalHtml():'';const results=node.querySelector?.('.op-modal-results');if(results)results.scrollTop=scroll;document.body.classList.toggle('op-modal-open',equipmentModal.open||ritualModal.open||!!editorModal);if(focus){const input=$('op-equipment-search');input?.focus();input?.setSelectionRange(input.value.length,input.value.length)}}
const editorTitles={cadastro:'Editar personagem',combate:'Armas e ataques',habilidades:'Editar habilidades',pericias:'Treinamento de perícias',progressao:'Progressão e poderes',inventario:'Editar inventário',rituais:'Editar rituais',anotacoes:'Editar anotações',guia:'Referências'};
function abilityModalHtml(){
 const groups=['Combatente','Especialista','Ocultista','Origens','Poderes Paranormais'];
 const group=abilityModal.group;
 const tracks=[...new Set(ABILITY_CATALOG.filter(a=>a.group===group&&a.track).map(a=>a.track))];
 const filtered=ABILITY_CATALOG.filter(a=>a.group===group&&(abilityModal.track==='Todos'||a.track===abilityModal.track)&&clean(`${a.name} ${a.description||''} ${a.track||''}`).includes(clean(abilityModal.search)));
 const owned=(draft&&view==='wizard'?draft.abilities:active()?.abilities)||[];
 return `<div class="op-modal-scrim" data-modal-overlay><section class="op-ritual-modal op-ability-modal" role="dialog" aria-modal="true" aria-label="Adicionar habilidades"><header class="op-modal-head"><div><small>PODERES E HABILIDADES · REGRAS V1.2</small><h2>Adicionar habilidades</h2></div><button class="op-modal-close" data-action="close-ability-catalog" aria-label="Fechar">×</button></header><div class="op-modal-toolbar"><div class="op-modal-elements">${groups.map(g=>`<button data-action="ability-group" data-group="${attr(g)}" class="${group===g?'active':''}">${esc(g)}</button>`).join('')}</div>${tracks.length?`<div class="op-modal-circles">${['Todos',...tracks].map(t=>`<button class="${abilityModal.track===t?'active':''}" data-action="ability-track" data-track="${attr(t)}">${esc(t)}</button>`).join('')}</div>`:''}<input id="op-ability-search" data-ability-search type="search" placeholder="Buscar habilidades, trilhas e efeitos" value="${attr(abilityModal.search)}" autocomplete="off"><small>${filtered.length} habilidades · toque para expandir e adicionar</small></div><div class="op-modal-results">${filtered.map(a=>{const open=abilityModal.expanded===a.id;const selected=owned.some(x=>x.catalogId===a.id);return `<article class="op-modal-ritual"><div class="op-modal-ritual-row"><button class="op-modal-expand" data-action="ability-expand" data-id="${attr(a.id)}" aria-expanded="${open}"><span class="op-modal-chevron">${open?'⌄':'›'}</span><strong>${esc(a.name)}</strong><small>${esc(a.track||a.group)}</small></button><button class="op-btn op-btn-primary op-add-ritual" data-action="ability-pick" data-id="${attr(a.id)}" aria-label="Adicionar ${attr(a.name)}">${selected?'✓':'+'}</button></div>${open?`<div class="op-modal-detail"><span class="op-tag">${esc(a.track||a.group)}${a.nex?' · NEX '+a.nex+'%':''}</span><p>${esc(a.description||'Efeito editável após adicionar. Consulte o livro para condições e pré-requisitos completos.')}</p><small>Referência: Ordem Paranormal RPG v1.2, página ${a.page||'a consultar'}. Confira os pré-requisitos no livro.</small><button class="op-btn op-btn-subtle" data-action="ability-pick" data-id="${attr(a.id)}">+ Adicionar à ficha</button></div>`:''}</article>`}).join('')||'<p class="op-empty">Nenhuma habilidade encontrada para os filtros.</p>'}</div><footer class="op-modal-footer"><span>Os efeitos selecionados podem ser editados.</span><button class="op-btn op-btn-subtle" data-action="close-ability-catalog">Fechar</button></footer></section></div>`;
}
function refreshAbilityModal(focus=false){let node=$('op-ability-modal-root');if(!node){node=document.createElement('div');node.id='op-ability-modal-root';document.body.appendChild(node)}const scroll=node.querySelector?.('.op-modal-results')?.scrollTop||0;node.innerHTML=abilityModal.open?abilityModalHtml():'';const list=node.querySelector?.('.op-modal-results');if(list)list.scrollTop=scroll;document.body.classList.toggle('op-modal-open',abilityModal.open||ritualModal.open||equipmentModal.open||!!editorModal);if(focus){const input=$('op-ability-search');input?.focus();input?.setSelectionRange(input.value.length,input.value.length)}}
function refreshEditorModal(){let node=$('op-editor-modal-root');if(!node){node=document.createElement('div');node.id='op-editor-modal-root';document.body.appendChild(node)}const c=active();if(!editorModal||!c){node.innerHTML='';document.body.classList.toggle('op-modal-open',ritualModal.open||equipmentModal.open||abilityModal.open);return}const d=derive(c),f=validate(c);const generators={'atributos-rapidos':()=>renderQuickAttributes(c,d),'defesa-rapida':()=>renderQuickDefense(c,d),cadastro:()=>renderSheet(c,d,f),combate:()=>renderAttacks(c),habilidades:()=>renderAbilities(c),pericias:()=>renderSkills(c,d),progressao:()=>renderProgression(c,d,f),inventario:()=>renderItems(c,d),rituais:()=>renderRituals(c,d),anotacoes:()=>renderNotes(c),guia:()=>renderGuide()};const previousScroll=node.querySelector?.('.op-editor-scroll')?.scrollTop||0;node.innerHTML=`<div class="op-modal-scrim" data-modal-overlay><section class="op-ritual-modal op-editor-modal" role="dialog" aria-modal="true" aria-label="${esc(({'atributos-rapidos':'Ajustar atributos','defesa-rapida':'Defesa e resistência'})[editorModal]||editorTitles[editorModal]||'Editar ficha')}"><header class="op-modal-head"><div><small>FICHA · ALTERAÇÕES SALVAS AUTOMATICAMENTE</small><h2>${esc(({'atributos-rapidos':'Ajustar atributos','defesa-rapida':'Defesa e resistência'})[editorModal]||editorTitles[editorModal]||'Editar ficha')}</h2></div><button class="op-modal-close" data-action="close-editor" aria-label="Fechar">×</button></header><div class="op-editor-scroll">${generators[editorModal]?.()||''}</div><footer class="op-modal-footer"><span>As alterações aparecem na ficha e no painel do mestre.</span><button class="op-btn op-btn-primary" data-action="close-editor">Concluir</button></footer></section></div>`;document.body.classList.toggle('op-modal-open',true);const newScroll=node.querySelector?.('.op-editor-scroll');if(newScroll)newScroll.scrollTop=previousScroll}

function onClick(e){if(e.target?.matches?.('[data-modal-overlay]')){ritualModal.open=false;equipmentModal.open=false;abilityModal.open=false;editorModal='';refreshRitualModal();refreshEquipmentModal();refreshAbilityModal();refreshEditorModal();return}const button=e.target.closest('[data-action]');if(!button)return;const action=button.dataset.action,c=active();
 if(action==='toggle-tools'){$('op-topactions').classList.toggle('is-open');button.setAttribute('aria-expanded',String($('op-topactions').classList.contains('is-open')));return}
 if(action==='toggle-ritual-details'){const i=numeric(button.dataset.i);expandedRituals.has(i)?expandedRituals.delete(i):expandedRituals.add(i);render();return}
 if(action==='toggle-ritual-edit'){const i=numeric(button.dataset.i);editingRituals.has(i)?editingRituals.delete(i):editingRituals.add(i);render();return}
 if(action==='toggle-weapon-details'){const i=numeric(button.dataset.i);expandedWeaponDetails.has(i)?expandedWeaponDetails.delete(i):expandedWeaponDetails.add(i);render();return}
 if(action==='toggle-item'){const i=numeric(button.dataset.i);expandedItems.has(i)?expandedItems.delete(i):expandedItems.add(i);render();return}
 if(action==='open-ability-catalog'){editorModal='';refreshEditorModal();const target=draft&&view==='wizard'?draft:c;abilityModal={open:true,search:'',group:target?.classId==='especialista'?'Especialista':target?.classId==='ocultista'?'Ocultista':'Combatente',track:'Todos',expanded:'',own:false};refreshAbilityModal();return}
 if(action==='close-ability-catalog'){abilityModal.open=false;refreshAbilityModal();return}
 if(action==='ability-group'){abilityModal.group=button.dataset.group;abilityModal.track='Todos';abilityModal.expanded='';abilityModal.search='';refreshAbilityModal();return}
 if(action==='ability-track'){abilityModal.track=button.dataset.track;abilityModal.expanded='';refreshAbilityModal();return}
 if(action==='ability-expand'){abilityModal.expanded=abilityModal.expanded===button.dataset.id?'':button.dataset.id;refreshAbilityModal();return}
 if(action==='ability-pick'){const a=ABILITY_CATALOG.find(x=>x.id===button.dataset.id);const target=draft&&view==='wizard'?draft:c;if(!a||!target)return;target.abilities??=[];if(target.abilities.some(x=>x.catalogId===a.id)){toast('Habilidade já cadastrada; edite-a na ficha.');return}target.abilities.push({name:a.name,description:a.description||'',group:a.group,track:a.track||'',catalogId:a.id,notes:''});if(view==='wizard'&&draft){render()}else{commit()}refreshAbilityModal();toast(`Habilidade adicionada: ${a.name}`);return}
 if(action==='open-ritual-catalog'){editorModal='';refreshEditorModal();ritualModal={open:true,search:'',element:'Todos',circle:0,expanded:''};refreshRitualModal();return}
 if(action==='open-equipment-catalog'||action==='open-weapon-catalog'){editorModal='';refreshEditorModal();equipmentModal={open:true,search:'',type:'Todos',expanded:'',mode:action==='open-weapon-catalog'?'weapons':'items'};refreshEquipmentModal();return}
 if(action==='close-equipment-catalog'){equipmentModal.open=false;refreshEquipmentModal();return}
 if(action==='equipment-filter-type'){equipmentModal.type=button.dataset.type;equipmentModal.expanded='';refreshEquipmentModal();return}
 if(action==='equipment-expand'){equipmentModal.expanded=equipmentModal.expanded===button.dataset.id?'':button.dataset.id;refreshEquipmentModal();return}
 if(action==='equipment-pick'){const item=createFromCatalog('items',button.dataset.id);if(!item||!c)return;c.items??=[];c.items.push(item);commit();refreshEquipmentModal();toast(`Equipamento adicionado: ${item.name}`);return}
 if(action==='close-ritual-catalog'){ritualModal.open=false;refreshRitualModal();return}
 if(action==='ritual-filter-element'){ritualModal.element=button.dataset.element;ritualModal.expanded='';refreshRitualModal();return}
 if(action==='ritual-filter-circle'){ritualModal.circle=numeric(button.dataset.circle);ritualModal.expanded='';refreshRitualModal();return}
 if(action==='ritual-expand'){ritualModal.expanded=ritualModal.expanded===button.dataset.id?'':button.dataset.id;refreshRitualModal();return}
 if(action==='ritual-pick'){const item=createFromCatalog('rituals',button.dataset.id);if(!item)return;if(draft&&view==='wizard'){draft.rituals??=[];draft.rituals.push(item)}else if(c){c.rituals??=[];c.rituals.push(item);commit()}ritualModal.expanded=button.dataset.id;refreshRitualModal();toast(`Ritual adicionado: ${item.name}`);return}
 if(action==='wizard-cancel'){draft=null;view='sheets';render();return}
 if(action==='wizard-back'){wizardStep=Math.max(0,wizardStep-1);render();return}
 if(action==='wizard-next'){if(!draft)return;const error=wizardError(draft,wizardStep);if(error){const el=$('op-wiz-feedback');if(el)el.textContent=error;return}wizardStep=Math.min(WIZARD_STEPS.length-1,wizardStep+1);render();window.scrollTo?.(0,0);return}
 if(action==='wizard-remove-ritual'&&draft){draft.rituals.splice(numeric(button.dataset.i),1);render();return}
 if(action==='wizard-add-ability'&&draft){draft.abilities??=[];draft.abilities.push({name:'',description:''});render();return}
 if(action==='wizard-remove-ability'&&draft){draft.abilities.splice(numeric(button.dataset.i),1);render();return}
 if(action==='wizard-add-ritual'){draft.rituals.push({name:'',element:'',circle:1,note:''});render();return}
 if(action==='wizard-finish'){if(!draft)return;if(!draft.name?.trim()){$('op-wiz-feedback').textContent='Informe um nome para criar a ficha.';return}state.characters.push(draft);state.active=draft.id;draft=null;view='sheets';tab='ficha';commit();window.scrollTo?.(0,0);toast('Ficha criada e salva na campanha');return}
 if(action==='home'){view='campaigns';state.activeCampaign='';persist();render();return}
 if(action==='open-campaign'){state.activeCampaign=button.dataset.id;view='sheets';ensure();persist();render();return}
 if(action==='master'){view='master';persist();render();return}
 if(action==='sheets'){view='sheets';persist();render();return}
 if(action==='delete-campaign'){const id=button.dataset.id,camp=state.campaigns.find(x=>x.id===id);if(!camp||!confirm(`Excluir a campanha ${camp.name} e todas as suas fichas? Esta ação é permanente para todos.`))return;state.campaigns=state.campaigns.filter(x=>x.id!==id);state.characters=state.characters.filter(x=>x.campaignId!==id);if(state.activeCampaign===id){state.activeCampaign='';view='campaigns'}persist();render();if(shared)enqueue(id,()=>shared.deleteCampaign(id));toast('Campanha excluída');return}
 if(action==='quick-resource'){const target=state.characters.find(x=>x.id===button.dataset.id&&x.campaignId===state.activeCampaign);if(!target)return;const resource=button.dataset.resource;Object.assign(target,button.dataset.mode==='spend'?spend(target,resource,1):recover(target,resource,1));target.lastEdited=new Date().toISOString();persist();render();if(shared){const snapshot=structuredClone(target);enqueue(target.id,()=>shared.saveCharacter(snapshot))}return}
 if(action==='tab'){if(button.dataset.tab==='ficha'){editorModal='';tab='ficha';render();refreshEditorModal();return}editorModal=button.dataset.tab;tab='ficha';render();refreshEditorModal();return}
 if(action==='close-editor'){editorModal='';refreshEditorModal();return}
 if(action==='select'){state.active=button.dataset.id;view='sheets';tab='ficha';persist();render();return}
 if(action==='new'){if(!campaign())return;draft=createDraft(state.activeCampaign,uid());wizardStep=0;view='wizard';render();window.scrollTo?.(0,0);return}
 if(action==='delete'){if(prompt(`EXCLUSÃO DEFINITIVA para todos os jogadores. Digite o nome exato da ficha (${c.name}) para confirmar:`)!==c.name)return;state.characters=state.characters.filter(x=>x.id!==c.id);state.active=campaignChars()[0]?.id||'';persist();render();if(shared)enqueue(c.id,()=>shared.deleteCharacter(c.id));toast('Ficha excluída');return}
 if(action==='resource'){const r=button.dataset.resource,n=numeric(document.querySelector(`[data-resource-amount="${r}"]`)?.value,1);if(n<=0){toast('Digite uma quantidade positiva');return}Object.assign(c,button.dataset.mode==='recover'?recover(c,r,n):spend(c,r,n));commit();return}
 if(action==='nex'){Object.assign(c,changeNex(c,numeric(button.dataset.nex)));commit();return}

 if(action==='reset-final-stat'){if(!c)return;const key=button.dataset.stat;if(!['defenseOverride','dodgeOverride','blockOverride'].includes(key))return;c[key]=null;commit();return}
 if(action==='remove-power'){if(!c)return;const i=numeric(button.dataset.i);if(!c.powers?.[i])return;if(!confirm(`Remover o poder ${c.powers[i]}?`))return;c.powers[i]='';commit();return}
 if(action==='add-attack'){c.attacks??=[];c.attacks.push({name:'',damage:'',critical:'20/x2',notes:''});commit();return}
 if(action==='remove-attack'){c.attacks?.splice(numeric(button.dataset.i),1);commit();return}
 if(action==='add-ability'){c.abilities??=[];c.abilities.push({name:'',description:''});commit();return}
 if(action==='remove-ability'){const i=numeric(button.dataset.i);if(!c.abilities?.[i]||!confirm(`Remover habilidade ${c.abilities[i].name||''}?`))return;c.abilities.splice(i,1);commit();return}
 if(action==='add-item'){c.items??=[];c.items.push({name:'',type:'Outro',category:0,space:1,qty:1});commit();return}
 if(action==='remove-item'){const i=numeric(button.dataset.i);if(!c.items?.[i]||!confirm(`Remover item ${c.items[i].name||''}?`))return;c.items.splice(i,1);expandedItems.delete(i);expandedWeaponDetails.delete(i);commit();return}
 if(action==='add-ritual'){c.rituals??=[];c.rituals.push({name:'',element:'',circle:1,note:''});commit();return}
 if(action==='remove-ritual'){const i=numeric(button.dataset.i);if(!c.rituals?.[i]||!confirm(`Remover ritual ${c.rituals[i].name||''}?`))return;c.rituals.splice(i,1);expandedRituals.clear();editingRituals.clear();commit();return}
 if(action==='cast'){const ritual=c.rituals[numeric(button.dataset.i)];if(!ritual)return;const cost=RITUAL_COST[ritual.circle];if(!cost)return;const current=derive(c).current.pe;if(current<cost){toast(`PE insuficientes (${current}/${cost})`);return}if(!confirm(`Conjurar ${ritual.name||'ritual'} e gastar ${cost} PE? Verifique os demais requisitos no livro.`))return;Object.assign(c,spend(c,'pe',cost));commit();return}
 if(action==='export'){const output={format:'ordem-paranormal-campaigns-v2',exportedAt:new Date().toISOString(),campaigns:state.campaigns,characters:state.characters};const blob=new Blob([JSON.stringify(output,null,2)],{type:'application/json'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download='ordem-paranormal-fichas.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),3000);return}
}
init();
document.addEventListener('click',onClick);
document.addEventListener('input',e=>{
 const t=e.target;
 if(t?.matches?.('[data-ritual-search]')){ritualModal.search=t.value;refreshRitualModal(true);return}
 if(t?.matches?.('[data-ability-search]')){abilityModal.search=t.value;refreshAbilityModal(true);return}
 if(t?.matches?.('[data-equipment-search]')){equipmentModal.search=t.value;refreshEquipmentModal(true);return}
 if(!t?.matches?.('[data-filter-catalog],[data-filter-wizard-catalog]'))return;
 const root=t.closest('.op-catalog-picker')||t.closest('.op-wiz-catalog-picker');
 const select=root?.querySelector('select');if(!select)return;
 const term=t.value.toLocaleLowerCase('pt-BR').normalize('NFD').replace(/[\u0300-\u036f]/g,'');
 for(const option of select.options){
  const normalized=option.textContent.toLocaleLowerCase('pt-BR').normalize('NFD').replace(/[\u0300-\u036f]/g,'');
  option.hidden=!!term&&!normalized.includes(term)&&!!option.value;
 }
 select.selectedIndex=0;
});
document.addEventListener('keydown',e=>{if(e.key==='Escape'){ritualModal.open=false;equipmentModal.open=false;abilityModal.open=false;editorModal='';refreshRitualModal();refreshEquipmentModal();refreshAbilityModal();refreshEditorModal()}});
document.addEventListener('change',e=>{if(e.target.id!=='import-file')onEdit(e)});
$('op-landing').addEventListener('submit',async e=>{if(e.target.id!=='op-create-form')return;e.preventDefault();const input=$('campaign-name');const name=(input?.value||'').trim();if(!name||name.length>120){toast('Informe um nome de até 120 caracteres.');return}const c={id:uid(),name};state.campaigns.push(c);state.activeCampaign=c.id;view='sheets';persist();render();if(shared)enqueue(c.id,()=>shared.saveCampaign(c));toast('Campanha criada');});
$('import-file').addEventListener('change',async e=>{const file=e.target.files?.[0];if(!file)return;try{if(file.size>5_000_000)throw Error('Arquivo grande demais.');const parsed=JSON.parse(await file.text());if(!Array.isArray(parsed.characters))throw Error('Backup incompatível.');if(parsed.characters.length>500)throw Error('Limite de fichas excedido.');let targetCampaign=campaign();if(!targetCampaign){const name=`Campanha importada ${new Date().toLocaleDateString('pt-BR')}`;targetCampaign={id:uid(),name};state.campaigns.push(targetCampaign);if(shared)await shared.saveCampaign(targetCampaign)}const imported=parsed.characters.filter(x=>x&&typeof x==='object'&&CLASSES[x.classId]&&NEX_STEPS.includes(Number(x.nex))).map(x=>({...initialCharacter(),...x,id:uid(),campaignId:targetCampaign.id})).map(restoreCharacterCatalog);if(!imported.length)throw Error('Nenhuma ficha válida encontrada.');if(!confirm(`Importar ${imported.length} fichas para ${targetCampaign.name}?`))return;state.characters.push(...imported);state.activeCampaign=targetCampaign.id;state.active=imported[0].id;view='sheets';persist();render();if(shared)for(const c of imported)enqueue(c.id,()=>shared.saveCharacter(c));toast(`${imported.length} fichas importadas`)}catch(err){toast(err.message)}finally{e.target.value=''}});
// Local mode: update other browser tabs on the same device.
window.addEventListener('storage',e=>{if(!shared&&e.key===KEY){read();ensure();render()}});
